function requireRepoMcpBinary(root: string): string {
  const bin = resolveMcpBin(root);
  if (!existsSync(bin) || !statSync(bin).isFile()) throw new Error(`repo MCP client binary is missing at ${bin}; run: bun nx run repo-mcp:build`);
  return bin;
}

export { Script };

function ensureFrameworkOsPlaygroundCatalog() {
  const catalog = loadFrameworkOsPlaygroundSelections();
  if (catalog.length === 0) throw new Error("No authored playground declarations were discovered");
  return catalog;
}

function resolvePlaygroundDevApp(segments: string[]): { readonly app: string; readonly rest: string[] } | null {
  const resolved = resolveFrameworkOsPlaygroundPlugin(ensureFrameworkOsPlaygroundCatalog(), segments);
  if (!resolved) return null;
  return { app: resolved.plugin, rest: [...resolved.rest] };
}

/** 🍽️ A bare `dev <variant>` under `SEMIO_RENDERER=react` runs the variant's whole Nx activation
 * chain — every selected plugin's `component-<profile>`/`materialize-<profile>`, the browser support
 * bundle, the guest fonts, the engine `wasm` producers, the generated playground session, then
 * `prepare` and `activate` — before Vite serves the receipt (os-dev `DevScript`).
 *
 * `served` opts out of that chain and serves whatever `dist/<profile>/🔌️plugin-modules/` and
 * `dist/runtime/<profile>/<variant>/activation/` already hold, for a boot that must not wait on (or
 * contend for) the shared Cargo lock. It also forces react, because
 * `frameworkOsPlaygroundDevEnv` defaults `SEMIO_RENDERER` to `wgpu` — a bare `dev s` otherwise builds
 * the whole catalog and hands off to `trunk serve`, never to Vite on `S_OS_PORT`.
 *
 * It is a command segment rather than an env var so it stays reachable from `launch.json`, which is
 * how every dev here starts things and which carries no `env` field.
 *
 * The renderer is selected by the *target*, never forced by a server script: `@semio-tech/framework-
 * os-dev:dev` is an alias that `resolveNxInvocation` (root `package.json`'s `nx` wrapper) rewrites to
 * `<dev|serve>-<variant>-<react|wgpu>-<dev|release>` from `SEMIO_PLUGIN`/`SEMIO_RENDERER`/
 * `SEMIO_BUILD_MODE`. Only the resolved wgpu target reaches the wgpu browser server, so its
 * `SEMIO_RENDERER = "wgpu"` assignment can never overrule a react launch row.
 *
 * `dev s` IS the all-plugins hub: `space` declares `[package.metadata.semio].host`, and every layer
 * keys off that one declaration — `runtimeComponentClosure` fans the Nx closure out to every
 * registered component, `buildPlaygroundSession`/`expandPluginRegistry` return the whole registry
 * unfiltered, and both renderers boot from that list. There is no separate multi-plugin variant to
 * select; a `dev multi` segment existed once and never resolved past this file. */
function runFrameworkOsPlaygroundDev(plugin: string, rest: string[] = []): void {
  const served = rest.includes("served");
  runCmd("bun", ["nx", "run", "@semio-tech/framework-os-dev:dev", "--", plugin, ...rest], {
    cwd: WORKSPACE_ROOT,
    env: frameworkOsPlaygroundDevEnv(ensureFrameworkOsPlaygroundCatalog(), plugin, served ? { SEMIO_RENDERER: "react" } : {}),
    ...daemonBudgetOpts(),
  });
}

//#region 🔖️NativeOsScript
/** 🖥️Runs the native bootstrap under `repo/native/bootstrap`. */
export class NativeOsScript extends Script {
  run(segments: string[]): void {
    const cmd = segments[0] ?? "setup";
    const env = { ...process.env };
    if (process.platform === "win32") {
      const ps1 = join(NATIVE_BOOTSTRAP_DIR, "🔵️.ps1");
      if (!existsSync(ps1)) {
        console.error(`[native] missing ${ps1}; expected repo/native/bootstrap/🔵️.ps1.`);
        process.exit(1);
      }
      runCmd("powershell.exe", ["-NoProfile", "-ExecutionPolicy", "Bypass", "-File", ps1, cmd], { cwd: this.root, env });
      return;
    }
    if (process.platform === "darwin" || process.platform === "linux") {
      const sh = join(NATIVE_BOOTSTRAP_DIR, "🐚️.sh");
      if (!existsSync(sh)) {
        console.error(`[native] missing ${sh}; expected repo/native/bootstrap/🐚️.sh.`);
        process.exit(1);
      }
      runCmd("bash", [sh, cmd], { cwd: this.root, env });
      return;
    }
    console.error(`[native] unsupported platform ${process.platform}`);
    process.exit(1);
  }
}
//#endregion 🔖️NativeOsScript

//#region 🔖️SetupScript
/** 🔗️ Repo-relative instruction files `setup git` recreates as links to `AGENTS.md`, one per
 * client that cannot read `AGENTS.md` itself. `codex`, `cursor-chat`, `windsurf-chat`, `droid` and
 * `kiro-cli` read the canonical file directly and need no alias; `claude-code` reads `CLAUDE.md`,
 * `antigravity-chat` reads `GEMINI.md`, and `copilot-chat` reads only `.github/copilot-instructions.md`.
 * @see AGENTS.md */
export const AGENT_INSTRUCTION_ALIASES = ["CLAUDE.md", "GEMINI.md", ".github/copilot-instructions.md"] as const;

/** 🧷️ The repo-local git settings `setup git` writes into `.git/config`; the user's global git config is never
 * touched. `core.longpaths` lets Git for Windows check out, track and clean paths past `MAX_PATH` (tracked fixture paths
 * reach 210 UTF-16 units below the clone root; git ignores the key elsewhere) and `core.symlinks` materializes the
 * committed symlinks. A first clone on Windows needs `git clone -c core.longpaths=true`, which writes the same key.
 * @see README.md */
export const REPO_LOCAL_GIT_CONFIG = [
  ["core.symlinks", "true"],
  ["core.longpaths", "true"],
] as const;

export class SetupScript extends Script {
  async run(segments: string[]): Promise<void> {
    if (!segments[0]) {
      this.runFull();
      return;
    }
    await dispatchSubcommand(
      segments,
      {
        postinstall: () => this.runPostinstall(),
        git: () => this.runGit(),
        native: (rest) => new NativeOsScript(this.root, this.repoRoot).run(rest),
        deps: (rest) => new NativeDependenciesScript(this.root, this.repoRoot).run(rest),
        prepare: () => console.log("[prepare] Nx prerequisites completed"),
        devcontainer: (rest) => this.runDevcontainer(rest),
      },
      "bun ./📜️script.ts setup [postinstall|git|native|deps|prepare|devcontainer <start|attach|gitkraken>]",
    );
  }

  /** 🔁️ The devcontainer lifecycle `.devcontainer/devcontainer.json` runs: `start` on every container start, `attach` on
   * every editor attach, `gitkraken` to open GitKraken Desktop on the checkout. Loaded on demand, so no other verb pays for it.
   * @see 🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/⚡️caching/📦️artifacts/🐳️containers/🔁️lifecycle/🟦️.ts */
  private async runDevcontainer(segments: string[]): Promise<void> {
    const lifecycle = await import("./🧰️framework/🛍️products/🦑️repo/🔨️modules/📚️library/⚡️caching/📦️artifacts/🐳️containers/🔁️lifecycle/🟦️.ts");
    const host = lifecycle.processLifecycleHost(), context = lifecycle.processLifecycleContext(this.root);
    await dispatchSubcommand(
      segments,
      { start: () => lifecycle.devcontainerStart(host, context), attach: () => lifecycle.devcontainerAttach(host, context), gitkraken: () => lifecycle.launchGitKraken(host, context) },
      "bun ./📜️script.ts setup devcontainer <start|attach|gitkraken>",
    );
  }

  private runPostinstall(): void {
    const pkgPath = join(this.root, "node_modules", "lightningcss", "package.json");
    if (!existsSync(pkgPath)) return;
    const { version } = JSON.parse(readFileSync(pkgPath, "utf8")) as { version: string };
    const report = process.report?.getReport?.() as { header?: { glibcVersionRuntime?: string } } | undefined;
    const libc = process.platform === "linux" ? (report?.header?.glibcVersionRuntime ? "gnu" : "musl") : "";
    const key = [process.platform, process.arch, libc].filter(Boolean).join("/");
    const pkgByKey: Record<string, string> = {
      "win32/x64": "lightningcss-win32-x64-msvc",
      "win32/arm64": "lightningcss-win32-arm64-msvc",
      "darwin/x64": "lightningcss-darwin-x64",
      "darwin/arm64": "lightningcss-darwin-arm64",
      "linux/x64/gnu": "lightningcss-linux-x64-gnu",
      "linux/x64/musl": "lightningcss-linux-x64-musl",
      "linux/arm64/gnu": "lightningcss-linux-arm64-gnu",
      "linux/arm64/musl": "lightningcss-linux-arm64-musl",
    };
    const platformPkg = pkgByKey[key];
    if (!platformPkg) return;
    if (existsSync(join(this.root, "node_modules", platformPkg))) return;
    runCmd("bun", ["add", "--no-save", `${platformPkg}@${version}`], { cwd: this.root });
  }

  private runGit(): void {
    for (const [key, value] of REPO_LOCAL_GIT_CONFIG) runCmd("git", ["config", "--local", key, value], { cwd: this.root });
    installMicroCommitGitHooks(this.root);
    const source = "AGENTS.md";
    for (const alias of AGENT_INSTRUCTION_ALIASES) {
      const aliasPath = join(this.root, ...alias.split("/"));
      mkdirSync(dirname(aliasPath), { recursive: true });
      if (existsSync(aliasPath)) rmSync(aliasPath, { force: true });
      const target = relative(dirname(aliasPath), join(this.root, source)).replaceAll("\\", "/");
      try {
        symlinkSync(target, aliasPath, "file");
      } catch (error) {
        if (process.platform !== "win32") throw error;
        linkSync(join(this.root, source), aliasPath);
      }
    }
  }

  private runFull(): void {
    console.log("[setup] locked dependency environments are ready through the Nx prerequisite graph");
    console.log("[setup] staging semio-os-mcp so `.mcp.json` initialize never waits on a cold build");
    ensureMcpBinary(this.root);
  }
}
//#endregion 🔖️SetupScript

//#region 🔖️StartScript
export class StartScript extends Script {
  run(_segments: string[]): void {
    process.chdir(this.root);
    if (!existsSync(join(this.root, "node_modules", "nx", "package.json"))) {
      console.log("[start] node_modules incomplete — run `bun install` and `bun ./📜️script.ts setup`.");
      return;
    }

    if (process.env.DEVCONTAINER === "true") {
      console.log("[start] Devcontainer session ready.");
      return;
    }

    if (process.env.S_LOCAL_ONLY !== "1" && process.env.S_LOCAL_ONLY !== "true") {
      process.env.S_HUB_URL = process.env.S_HUB_URL || "http://127.0.0.1:8787";
      process.env.OS_HUB_DATA = process.env.OS_HUB_DATA || join(this.root, ".🧬semio", "🌐hub", "hub-dev");
      spawnDaemon("bun", ["nx", "run", "@semio-tech/framework-os-dev:local-hub"], {
        cwd: this.root,
        env: process.env,
        stdio: "ignore",
      });
      console.log(`[start] local development hub owner launching at ${process.env.S_HUB_URL} (data ${process.env.OS_HUB_DATA}, log local-hub.log there); every \`dev s\` row signs in through its session broker`);
    }
    if (process.platform !== "win32" && process.platform !== "darwin" && process.platform !== "linux") {
      console.log(`[start] Unsupported platform ${process.platform}.`);
    }
  }
}
//#endregion 🔖️StartScript

//#region 🔖️DevScript
export class DevScript extends Script {
  async run(segments: string[]): Promise<void> {
    if (segments[0] === "storybook") {
      await this.runStorybook(segments.slice(1));
      return;
    }
    if (segments[0] === "storybook-static") {
      await this.runStorybookStatic();
      return;
    }
    if (segments[0] === "s") {
      runFrameworkOsPlaygroundDev("s", segments.slice(1));
      return;
    }
    if (segments[0] === "mcp") {
      this.runMcp(segments.slice(1));
      return;
    }
    const playgroundApp = resolvePlaygroundDevApp(segments);
    if (playgroundApp) {
      runFrameworkOsPlaygroundDev(playgroundApp.app, playgroundApp.rest);
      return;
    }
    if (segments.length > 0) {
      console.error(`[dev] unknown playground app ${JSON.stringify(segments.join(" "))} — regenerate the catalog with bun nx run @semio-tech/plugin-registry:generate if the variant should exist.`);
      process.exit(1);
    }
    runFrameworkOsPlaygroundDev("s");
  }

  private async parseStorybookSegments(segments: string[]): Promise<{ scope: string; args: string[] }> {
    const scopeSegments: string[] = [];
    const args: string[] = [];
    let parsingScope = true;
    for (const segment of segments) {
      if (parsingScope && segment !== "--" && !segment.startsWith("-")) {
        scopeSegments.push(segment);
        continue;
      }
      parsingScope = false;
      if (segment !== "--") args.push(segment);
    }
    // A single scope arg may itself be a comma-list of top-level scopes ("ui,framework/os").
    // Multiple space-separated args keep slash-join behavior for hierarchical scopes ("framework" "os" -> "framework/os").
    const scope = scopeSegments.length === 1 && scopeSegments[0]!.includes(",") ? scopeSegments[0]! : scopeSegments.join("/");
    const scopeIds = scope
      ? scope
          .split(",")
          .map((s) => s.trim())
          .filter(Boolean)
      : [];
    for (const id of scopeIds) {
      if (!/^[a-z0-9][a-z0-9/-]*$/i.test(id)) {
        console.error(`[dev.storybook] invalid scope ${JSON.stringify(id)}`);
        process.exit(1);
      }
    }
    if (scopeIds.length > 0) {
      try {
        const { resolveActiveScopes } = await import("./.storybook/📖️stories/🧭️coordination/🟦️.ts");
        resolveActiveScopes(scopeIds.join(","));
      } catch (error) {
        console.error(error instanceof Error ? `[dev.storybook] ${error.message}` : error);
        process.exit(1);
      }
    }
    return { scope: scopeIds.join(","), args };
  }

  private async runStorybook(extra: string[]): Promise<void> {
    const storybook = await this.parseStorybookSegments(extra);
    const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
    const port = process.env.STORYBOOK_PORT ?? "6010";
    const useExactPort = process.env.STORYBOOK_EXACT_PORT === "1" || process.env.STORYBOOK_EXACT_PORT === "true";
    const storybookArgs = ["storybook", "dev", "-c", ".storybook", "-p", port, ...(useExactPort ? ["--exact-port"] : []), "--host", host, "--no-open", "--debug", ...storybook.args];
    runCmd(process.execPath, ["x", ...storybookArgs], {
      cwd: this.root,
      env: {
        ...process.env,
        STORYBOOK_SCOPE: storybook.scope,
        WATCHPACK_POLLING: process.env.WATCHPACK_POLLING ?? "true",
        CHOKIDAR_USEPOLLING: process.env.CHOKIDAR_USEPOLLING ?? "true",
      },
      ...daemonBudgetOpts(),
    });
  }

  private async runStorybookStatic(): Promise<void> {
    const host = process.env.STORYBOOK_STATIC_HOST ?? "0.0.0.0";
    const port = Number(process.env.STORYBOOK_PORT ?? "6010");
    const documentRoot = resolve(this.root, "storybook-static");
    const server = Bun.serve({
      hostname: host,
      port,
      async fetch(request) {
        const requestUrl = new URL(request.url);
        const requestPath = decodeURIComponent(requestUrl.pathname);
        const candidatePath = resolve(documentRoot, `.${requestPath}`);
        if (!candidatePath.startsWith(documentRoot)) return new Response("Forbidden", { status: 403 });
        const filePath = await (async () => {
          try {
            const fileInfo = await stat(candidatePath);
            if (fileInfo.isDirectory()) return resolve(candidatePath, "🌐️.html");
            return candidatePath;
          } catch {
            if (extname(candidatePath) === "") return resolve(candidatePath, "🌐️.html");
            return candidatePath;
          }
        })();
        try {
          const file = Bun.file(filePath);
          if (!(await file.exists())) return new Response("Not Found", { status: 404 });
          return new Response(file);
        } catch {
          return new Response("Not Found", { status: 404 });
        }
      },
    });

    console.log(`storybook-static listening on http://${host}:${port}`);
    await new Promise(() => {});
  }

  private runMcp(segments: string[]): void {
    const a = segments[0];
    if (a === "stdio") {
      const rest = segments.slice(1);
      if ((rest[0] ?? "").trim().toLowerCase() === "os") {
        this.runMcpOs("stdio", rest.slice(1));
        return;
      }
      this.runMcpStdioRepo(rest);
      return;
    }
    if (a === "http") {
      const rest = segments.slice(1);
      if ((rest[0] ?? "").trim().toLowerCase() === "os") {
        this.runMcpOs("http", rest.slice(1));
        return;
      }
      console.error("[dev] `dev mcp http` currently serves only the os gateway — use `dev mcp http os`.");
      process.exit(1);
    }
    const mode = a === "repo" ? "repo" : "default";
    const host = process.env.DEVCONTAINER === "true" ? "0.0.0.0" : "127.0.0.1";
    if (mode === "repo") {
      runCmd(process.execPath, ["x", "@modelcontextprotocol/inspector", "--config", ".cursor/mcp.json", "--server", "repo"], {
        cwd: this.root,
        env: { ...process.env, HOST: host },
        ...daemonBudgetOpts(),
      });
      return;
    }
    runCmd(process.execPath, ["x", "@modelcontextprotocol/inspector"], { cwd: this.root, ...daemonBudgetOpts() });
  }

  /** 🌉️ Runs the `semio-os` MCP gateway (`semio-framework-os-mcp`) over stdio or Streamable HTTP.
   * `stdio` is what `.mcp.json` launches; `http` defaults to port 6300 (outside the 6012–6205
   * catalog range and the 7300+ bench pool). Extra argv passes straight through to the binary
   * (`--folder`, `--hub`, `--principal`, `--scopes`, `--auto-approve`, …). */
  private runMcpOs(transport: "stdio" | "http", extra: string[]): void {
    const args = [transport, ...extra];
    if (transport === "http" && !extra.includes("--port")) {
      args.push("--port", process.env.S_OS_MCP_PORT ?? "6300");
    }
    runCmd(ensureMcpBinary(this.root), args, { cwd: this.root, ...daemonBudgetOpts() });
  }

  private runMcpStdioRepo(slugs: string[]): void {
    if (slugs.length > 1) {
      console.error("[dev] `dev mcp stdio` accepts one repo client profile.");
      process.exit(1);
    }
    const profile = (slugs[0] ?? "client").trim().toLowerCase();
    const bin = requireRepoMcpBinary(this.root);
    runCmd(bin, [], { cwd: this.root, ...daemonBudgetOpts({ GOWORK: join(this.root, "go.work"), [REPO_MCP_PROFILE_ENV]: profile }) });
  }
}
//#endregion 🔖️DevScript



//#region 🔖️GenerateScript
function taxonomyOption(args: readonly string[], name: string): string | undefined {
  const index = args.indexOf(name);
  return index >= 0 ? args[index + 1] : undefined;
}

function taxonomyContractFilename(taxonomy: ReturnType<typeof loadTaxonomy>, contractId: string): string {
  const fixed = taxonomy.fixedFilenameContracts[contractId];
  const filename = fixed ? fixedContractFilename(fixed) : taxonomy.configurableEntryContracts[contractId]?.filename;
  if (!filename) throw new Error(`[taxonomy] unknown filename contract ${JSON.stringify(contractId)}.`);
  return filename;
}

function taxonomyContractFilenames(taxonomy: ReturnType<typeof loadTaxonomy>, contractIds: readonly string[]): string[] {
  return contractIds.map((contractId) => taxonomyContractFilename(taxonomy, contractId));
}

function taxonomyMappedFilename(taxonomy: ReturnType<typeof loadTaxonomy>, mapping: Readonly<Record<string, string>>, key: string): string {
  const fileKindId = mapping[key];
  if (!fileKindId) throw new Error(`[taxonomy] no file-kind mapping for ${JSON.stringify(key)}.`);
  return canonicalPrimaryFilenameForKind(fileKindId, taxonomy);
}

function taxonomyEcosystemEntryFilenames(taxonomy: ReturnType<typeof loadTaxonomy>, ecosystemId: string): string[] {
  return taxonomyContractFilenames(taxonomy, taxonomy.ecosystems[ecosystemId]?.entryContractIds ?? []);
}



export class GenerateScript extends Script {
  run(segments: string[]): void {
    if (segments[0] === "taxonomy") {
      this.generateTaxonomy(segments.slice(1));
      return;
    }
    if (segments[0] === "plugin-glue") {
      this.generatePluginGlue(segments.slice(1));
      return;
    }
    if (segments[0] === "scale-fixture") {
      runCmd("bun", ["nx", "run", "@semio-tech/framework-os-dev:generate-scale-fixture", ...segments.slice(1)], { cwd: this.root });
      return;
    }
    console.error("[generate] usage: bun ./📜️script.ts generate <taxonomy|plugin-glue|scale-fixture>");
    process.exit(1);
  }

  /** 🧩️ Writes deterministic census or duplicate evidence with its Markdown companion. */
  private generateTaxonomy(args: string[]): void {
    const operation = args[0];
    if (operation === "package-adapter") {
      runNestedCargoPackageAdapter(this.root, args[1] ?? "preview");
      return;
    }
    if (operation !== "census" && operation !== "duplicates") throw new Error(`[generate taxonomy] expected census or duplicates, got ${JSON.stringify(operation)}.`);
    const ticketId = taxonomyOption(args, "--ticket");
    if (!ticketId) throw new Error(`[generate taxonomy ${operation}] --ticket <ticket-id> is required.`);
    const ticketDir = taxonomyTicketDirectory(this.root, ticketId);
    const census = buildSemanticCensus(this.root);
    if (operation === "census") {
      writeFileSync(join(ticketDir, "📊️semantic-census.json"), renderSemanticCensusJson(census));
      writeFileSync(join(ticketDir, "📓️semantic-census.md"), renderSemanticCensusMarkdown(census));
    } else {
      writeFileSync(join(ticketDir, "📊️semantic-duplicates.json"), renderSemanticDuplicatesJson(census));
      writeFileSync(join(ticketDir, "📓️semantic-duplicates.md"), renderSemanticDuplicatesMarkdown(census));
    }
    console.log(`[generate taxonomy ${operation}] ${census.records.length} components, ${census.problems.length} findings -> ${ticketDir}`);
  }

  /** 🧬️ Emit deterministic #[path] wiring comments for subset/example modules (dry by default). */
  private generatePluginGlue(args: string[]): void {
    const dry = args.includes("--dry") || args.includes("--dry-run") || args.length === 0;
    const pluginFilter = args.find((a) => !a.startsWith("--"));
    const pluginsRoot = join(this.root, "✏️s/🔌️plugins");
    const plugins = readdirSync(pluginsRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name);
    let emitted = 0;
    for (const plugin of plugins) {
      if (pluginFilter && plugin !== pluginFilter && !plugin.includes(pluginFilter)) continue;
      const owned = policyListTopLevelSubsetDirs(this.root).filter((s) => s.split("/")[2] === plugin);
      const lines: string[] = [
        `// GENERATED-BY: bun ./📜️script.ts generate plugin-glue ${plugin}`,
        `// subsets=${owned.length} (registration body still hand-authored until serializer wave; this command validates discoverability)`,
      ];
      for (const sub of owned) {
        lines.push(`// subset: ${sub}`);
        emitted += 1;
      }
      const glue = join(pluginsRoot, plugin, "📦️packages/🦀️rust/🦀️.rs");
      if (!existsSync(glue)) {
        console.warn(`[generate plugin-glue] skip ${plugin}: missing glue.rs`);
        continue;
      }
      if (dry) {
        console.log(`[generate plugin-glue] dry ${plugin}: ${owned.length} subsets`);
      } else {
        const inv = join(pluginsRoot, plugin, "📦️packages/🦀️rust/🤖️generated-subset-inventory.txt");
        writeFileSync(inv, lines.join("\n") + "\n");
        console.log(`[generate plugin-glue] wrote ${inv}`);
      }
    }
    console.log(`[generate plugin-glue] ${dry ? "dry-run" : "wrote"} inventory for ${emitted} subset refs`);
  }
}
//#endregion 🔖️GenerateScript

//#region 🔖️LintScript
export class LintScript extends Script {
  run(segments: string[]): void {
    // nx orchestrators: exempt — total wall time spans every project and legitimately exceeds any single
    // command's budget; each leaf project's own build/test/lint commands are individually budgeted.
    if (segments[0] === "repo") {
      console.log("[lint] Nx completed the repository lint graph.");
      return;
    }
