/** 🎯️ Finds the matching Rust brace while ignoring quoted strings and comments. */
function toolJobRustBlock(source: string, open: number): { body: string; end: number } | undefined {
  let depth = 0;
  let string = false;
  let lineComment = false;
  let blockComment = 0;
  let escaped = false;
  for (let index = open; index < source.length; index += 1) {
    const char = source[index]!;
    const next = source[index + 1] ?? "";
    if (lineComment) {
      if (char === "\n") lineComment = false;
      continue;
    }
    if (blockComment > 0) {
      if (char === "/" && next === "*") {
        blockComment += 1;
        index += 1;
      } else if (char === "*" && next === "/") {
        blockComment -= 1;
        index += 1;
      }
      continue;
    }
    if (string) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') {
        string = false;
      }
      continue;
    }
    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }
    if (char === "/" && next === "*") {
      blockComment = 1;
      index += 1;
      continue;
    }
    if (char === '"') string = true;
    else if (char === "{") depth += 1;
    else if (char === "}" && --depth === 0) return { body: source.slice(open + 1, index), end: index + 1 };
  }
  return undefined;
}

function toolJobRustArray(source: string, open: number): { body: string; end: number } | undefined {
  if (source[open] !== "[") return undefined;
  let depth = 0;
  let string = false;
  let escaped = false;
  let lineComment = false;
  let blockComment = 0;
  for (let index = open; index < source.length; index += 1) {
    const char = source[index]!;
    const next = source[index + 1];
    if (lineComment) {
      if (char === "\n") lineComment = false;
      continue;
    }
    if (blockComment > 0) {
      if (char === "/" && next === "*") {
        blockComment += 1;
        index += 1;
      } else if (char === "*" && next === "/") {
        blockComment -= 1;
        index += 1;
      }
      continue;
    }
    if (string) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') string = false;
      continue;
    }
    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }
    if (char === "/" && next === "*") {
      blockComment = 1;
      index += 1;
      continue;
    }
    if (char === '"') string = true;
    else if (char === "[") depth += 1;
    else if (char === "]" && --depth === 0) return { body: source.slice(open + 1, index), end: index + 1 };
  }
  return undefined;
}

type ToolJobStaticRow = { file: string; id: string; source: "literal" | "macro" };

