//#region 🔖️GeneratedCorruptionCensus
/** 🚫️Directories the corruption census never walks: caches, vendored trees and build scratch own no repo source. */
const GENERATED_CORRUPTION_SKIP_DIRS = new Set(["node_modules", ".git", "target", "🎯️target", "⚡️cache", ".venv", ".nx", ".turbo", ".git-rewrite"]);

/** 🧩️The extensions `tsc` parses — the only files where a spliced emoji becomes a TS1127/TS1434 parse error. */
const GENERATED_CORRUPTION_EXTENSIONS = new Set([".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"]);

/** 🏷️jco stamps every world-level binding file with this first line; it selects generator output without guessing file names. */
const JCO_WORLD_HEADER = "// world ";

/** 📥️`export type * as <Alias> from './interfaces/<x>.js'; // import <wit-id>` — one imported interface of a jco world. */
const JCO_IMPORT_ALIAS_LINE = /^export type \* as (\S+) from '[^']+'; \/\/ import (\S+)\s*$/;

/** 📤️`export * as <alias> from './interfaces/<x>.js'; // export <wit-id>` — one exported interface of a jco world. */
const JCO_EXPORT_ALIAS_LINE = /^export \* as (\S+) from '[^']+'; \/\/ export (\S+)\s*$/;

/** 🔬️An emoji (with its optional VS16 / ZWJ / skin-tone tail) wedged between two ASCII identifier characters. */
const SPLICED_EMOJI_IDENTIFIER = /[A-Za-z0-9_$](\p{Extended_Pictographic}(?:️|︎|‍\p{Extended_Pictographic}|[\u{1F3FB}-\u{1F3FF}])*)[A-Za-z0-9_$]/gu;

/** 🔎️One spliced-emoji identifier, located precisely enough to be fixed without re-running the census. */
type GeneratedCorruptionFinding = {
  readonly kind: "jco-alias" | "code-position";
  readonly file: string;
  readonly line: number;
  readonly detail: string;
};

/** 📊️The whole census: what was looked at, what validated the jco naming rule, and every surviving finding. */
type GeneratedCorruptionCensus = {
  readonly filesScanned: number;
  readonly jcoFilesScanned: number;
  readonly jcoAliasesValidated: number;
  readonly findings: readonly GeneratedCorruptionFinding[];
};

/** 🐫️jco's identifier casing for one kebab/snake WIT segment. */
function jcoPascalSegment(segment: string): string {
  return segment
    .split(/[-_]/)
    .filter((part) => part.length > 0)
    .map((part) => part[0]!.toUpperCase() + part.slice(1))
    .join("");
}

/**
 * 🧬️Re-derives the world-level namespace alias jco emits for one WIT interface id, from the id alone:
 * `wasi:cli/environment@0.2.9` → `WasiCliEnvironment029` for an import, and the bare camelCase interface
 * name (`plugin`) for an export. This is the source of truth the corruption census checks bindings against.
 */
function jcoWorldAlias(witId: string, direction: "import" | "export"): string {
  const [head, version = ""] = witId.split("@");
  const segments = head!.split(/[:/]/).filter((segment) => segment.length > 0);
  if (direction === "export") {
    const last = jcoPascalSegment(segments[segments.length - 1] ?? "");
    return last.slice(0, 1).toLowerCase() + last.slice(1);
  }
  return segments.map(jcoPascalSegment).join("") + version.replace(/[.\-]/g, "");
}

/** 🧾️`ScriptKind` per extension, so JSX and TypeScript syntax are parsed by the rules their file actually uses. */
function typescriptScriptKindFor(fileName: string, ts: TypeScriptParserApi): number {
  if (fileName.endsWith(".tsx")) return ts.ScriptKind.TSX;
  if (fileName.endsWith(".jsx")) return ts.ScriptKind.JSX;
  if (/\.(js|mjs|cjs)$/.test(fileName)) return ts.ScriptKind.JS;
  return ts.ScriptKind.TS;
}

/** 🧰️The sliver of the TypeScript compiler this census uses: a parse, and the errors that parse produced. */
type TypeScriptParserApi = {
  readonly version: string;
  readonly ScriptTarget: { readonly Latest: number };
  readonly ScriptKind: { readonly TS: number; readonly TSX: number; readonly JS: number; readonly JSX: number };
  createSourceFile(fileName: string, text: string, target: number, setParentNodes: boolean, scriptKind: number): { readonly parseDiagnostics?: readonly { readonly start: number }[] };
};

/**
 * 🔬️Walks every TS/JS file the repo owns and reports emoji spliced into ASCII identifiers — the signature of
 * the 2026-09-03 rename-plan codemod incident. Two independent checks, neither of them a heuristic: jco
 * world bindings are validated against {@link jcoWorldAlias}, and every other candidate file is handed to
 * the repo's own TypeScript parser, so an emoji counts as spliced only where the parser reports an error at
 * that exact offset. That is what separates corruption from this repo's legitimate emoji-in-path/label
 * idiom, which parses cleanly inside strings, comments, regex literals and JSX text. Generated output is
 * walked deliberately: it is what the incident corrupted.
 */
function censusGeneratedCorruption(root: string): GeneratedCorruptionCensus {
  const findings: GeneratedCorruptionFinding[] = [];
  const ts = createRequire(join(root, "package.json"))("typescript") as TypeScriptParserApi;
  let filesScanned = 0;
  let jcoFilesScanned = 0;
  let jcoAliasesValidated = 0;

  const walk = (directory: string): void => {
    let entries: Dirent[];
    try {
      entries = readdirSync(directory, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const absolute = join(directory, entry.name);
      if (entry.isDirectory()) {
        if (!GENERATED_CORRUPTION_SKIP_DIRS.has(entry.name)) walk(absolute);
        continue;
      }
      if (!entry.isFile() || !GENERATED_CORRUPTION_EXTENSIONS.has(extname(entry.name))) continue;
      let source: string;
      try {
        source = readFileSync(absolute, "utf8");
      } catch {
        continue;
      }
      filesScanned += 1;
      const file = relative(root, absolute);
      if (source.startsWith(JCO_WORLD_HEADER)) {
        jcoFilesScanned += 1;
        source.split("\n").forEach((text, offset) => {
          const asImport = JCO_IMPORT_ALIAS_LINE.exec(text);
          const asExport = asImport ? null : JCO_EXPORT_ALIAS_LINE.exec(text);
          const match = asImport ?? asExport;
          if (!match) return;
          const expected = jcoWorldAlias(match[2]!, asImport ? "import" : "export");
          if (match[1] === expected) {
            jcoAliasesValidated += 1;
            return;
          }
          findings.push({ kind: "jco-alias", file, line: offset + 1, detail: `alias ${JSON.stringify(match[1])} ≠ ${JSON.stringify(expected)} derived from ${match[2]}` });
        });
        continue;
      }
      SPLICED_EMOJI_IDENTIFIER.lastIndex = 0;
      if (!SPLICED_EMOJI_IDENTIFIER.test(source)) continue;
      const parsed = ts.createSourceFile(absolute, source, ts.ScriptTarget.Latest, false, typescriptScriptKindFor(entry.name, ts));
      const errorOffsets = (parsed.parseDiagnostics ?? []).map((diagnostic) => diagnostic.start);
      if (errorOffsets.length === 0) continue;
      const lineStarts = [0];
      for (let at = source.indexOf("\n"); at >= 0; at = source.indexOf("\n", at + 1)) lineStarts.push(at + 1);
      SPLICED_EMOJI_IDENTIFIER.lastIndex = 0;
      let match: RegExpExecArray | null;
      while ((match = SPLICED_EMOJI_IDENTIFIER.exec(source)) !== null) {
        const from = match.index;
        const to = SPLICED_EMOJI_IDENTIFIER.lastIndex;
        if (SPLICED_EMOJI_IDENTIFIER.lastIndex === match.index) SPLICED_EMOJI_IDENTIFIER.lastIndex += 1;
        if (!errorOffsets.some((offset) => offset >= from && offset <= to)) continue;
        let start = from;
        while (start > 0 && /[A-Za-z0-9_$]/.test(source[start - 1]!)) start -= 1;
        let end = to;
        while (end < source.length && /[A-Za-z0-9_$]/.test(source[end]!)) end += 1;
        let line = 1;
        while (line < lineStarts.length && lineStarts[line]! <= from) line += 1;
        findings.push({ kind: "code-position", file, line, detail: `spliced ${match[1]} in identifier ${JSON.stringify(source.slice(start, end))} (TypeScript cannot parse it)` });
      }
    }
  };

  walk(root);
  return { filesScanned, jcoFilesScanned, jcoAliasesValidated, findings };
}
//#endregion 🔖️GeneratedCorruptionCensus

/** 🧪️Aggregates lint + generated-catalog freshness + region/host-contract script lints (`gate`, the cheap pre-`ticket_close` step every refactor session runs), plus the full test suite for the top-level `verify` verb. */
/** 🧸️One composed-child row of a committed `*.dsl.semio` document whose target names a different id than the row's own `child_id`. */
export type ComposedChildRefRow = { path: string; slot: string; childId: string; targetArtifactId: string; targetUri: string; waiver?: string };

/**
 * 🧾️The only rows `verify composed-child-refs` tolerates. `🌍️gis`'s durable three-store assembly
 * deliberately pins its member documents to fixed ids (`gismap-drawing`, `gismap-value`) that are
 * declared as constants in the framework's own durable-group composition
 * (`🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🧩️composition/🗄️durable-group/🦀️.rs`), in
 * `✏️s/🔌️plugins/🌍️gis/🧬️schema/🔣️.json` as `const`, and in `🌎️hub`'s committed fixtures — so the
 * parent's per-handle `child_id` and the member's stable document id are two different things on
 * purpose. The consequence is stated, not hidden: a durable-group child in that shape can never pass
 * `ChildRestoreProjection`, so gis cannot take a whole-document `Effect::LoadDocument` until that
 * fork is resolved by the durable-group owner. Each waiver names the id it protects.
 */
const COMPOSED_CHILD_REF_WAIVERS: { targetArtifactId: string; reason: string }[] = [
  { targetArtifactId: "gismap-drawing", reason: "gis durable-group member id, declared const in store/🗄️durable-group, gis 🧬️schema/🔣️.json and 🌎️hub fixtures" },
  { targetArtifactId: "gismap-value", reason: "gis durable-group member id, declared const in store/🗄️durable-group, gis 🧬️schema/🔣️.json and 🌎️hub fixtures" },
];

/** 🚫️Directory names the composed-child-ref walk never descends into — caches and build output carry copies of the same assets. */
const COMPOSED_CHILD_REF_SKIPPED_DIRECTORIES = new Set([".git", "node_modules", "dist", "target", "⚡️cache", "🗑️generated"]);

/** 📚️Every committed `*.dsl.semio` document in the workspace, in walk order. */
function verifyComposedChildRefAssets(root: string): string[] {
  const found: string[] = [];
  const walk = (directory: string): void => {
    let entries;
    try {
      entries = readdirSync(directory, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (!COMPOSED_CHILD_REF_SKIPPED_DIRECTORIES.has(entry.name)) walk(join(directory, entry.name));
      } else if (entry.name.endsWith(".dsl.semio")) found.push(join(directory, entry.name));
    }
  };
  walk(root);
  return found;
}

/** 🔢️Count of the documents the law scanned, so a zero-breach run still proves it looked at something. */
export function verifyComposedChildRefAssetCount(root: string): number {
  return verifyComposedChildRefAssets(root).length;
}

/**
 * 🔎️Scans every committed `*.dsl.semio` for child rows of the DSL shape
 * `<slot>=[<hex child_id>,<hex target uri>]` that `store::artifact_child_to_record` writes, and
 * returns the rows whose target uri names an artifact id other than the row's own `child_id`.
 * Rows matching `COMPOSED_CHILD_REF_WAIVERS` come back carrying their waiver reason rather than
 * being dropped, so the census always shows the whole truth.
 */
export function verifyComposedChildRefRows(root: string): ComposedChildRefRow[] {
  const rows: ComposedChildRefRow[] = [];
  const decode = (hex: string): string | undefined => {
    if (hex.length % 2 !== 0) return undefined;
    try {
      return Buffer.from(hex, "hex").toString("utf8");
    } catch {
      return undefined;
    }
  };
  for (const path of verifyComposedChildRefAssets(root)) {
    let text;
    try {
      text = readFileSync(path, "utf8");
    } catch {
      continue;
    }
    for (const line of text.split("\n")) {
      const match = /^([A-Za-z0-9_]+)=\[([0-9a-f]+),([0-9a-f]+)\]$/.exec(line.trim());
      if (match === null) continue;
      const childId = decode(match[2]);
      const targetUri = decode(match[3]);
      if (childId === undefined || targetUri === undefined || !targetUri.includes("!")) continue;
      const targetArtifactId = targetUri.slice(0, targetUri.indexOf("!"));
      if (targetArtifactId === childId) continue;
      const waiver = COMPOSED_CHILD_REF_WAIVERS.find((row) => row.targetArtifactId === targetArtifactId)?.reason;
      rows.push({ path: relative(root, path), slot: match[1], childId, targetArtifactId, targetUri, waiver });
    }
  }
  return rows;
}

/** 🧮️ The two production source censuses as gates (acceptance ledger 1.8 / 1.9): `placeholders` fails on any
 * `unimplemented!(` / `todo!(` in a production (non-test) Rust source; `commands` fails on any production command declared
 * `InteractiveJobClassification::BatchOnlyPendingRewrite` (unreachable from every control of the running app). Both
 * cross-check their scanner against `git grep`, print their table, and publish the acceptance record.
 * @see 🧰️framework/🛍️products/🦑️repo/🔨️modules/🧪️test/🎯️acceptance/📋️orchestration/🟦️.ts `runSourceCensus` */
async function runSourceCensusGate(root: string, which: "placeholders" | "commands"): Promise<void> {
  const { acceptanceCheckResult, publishAcceptanceCheckResult, runSourceCensus } = await import("./🧰️framework/🛍️products/🦑️repo/🔨️modules/🧪️test/🎯️acceptance/📋️orchestration/🟦️.ts");
  const controller = new AbortController();
  const cancel = (): void => controller.abort();
  process.once("SIGINT", cancel);
  const startedAt = new Date();
  try {
    const census = runSourceCensus(root, controller.signal, (line) => console.error(`[verify source-census] ${line}`));
    const oracleAgrees = census.placeholderDisagreements.length === 0 && census.callDisagreements.length === 0;
    if (which === "placeholders") {
      const production = census.placeholders.filter((hit) => !hit.testOnly && !hit.commented);
      for (const hit of census.placeholders.filter((entry) => !entry.commented)) console.log(`[verify production-placeholders] ${hit.testOnly ? "test" : "PRODUCTION"} ${hit.macro}! ${hit.path}:${hit.line}`);
      for (const disagreement of census.placeholderDisagreements) console.log(`[verify production-placeholders] oracle disagreement ${disagreement}`);
      const status = production.length === 0 && oracleAgrees ? "pass" : "fail";
      console.log(`[verify production-placeholders] files=${census.files} production=${production.length} test=${census.placeholders.filter((hit) => hit.testOnly && !hit.commented).length} commented=${census.placeholders.filter((hit) => hit.commented).length} oracle=${oracleAgrees ? "agrees" : "DISAGREES"}`);
      publishAcceptanceCheckResult(root, acceptanceCheckResult({
        check: "production-placeholders",
        status,
        startedAt,
        measured: { files: census.files, production: production.length, testOnly: census.placeholders.filter((hit) => hit.testOnly && !hit.commented).length, oracleAgrees },
        summary: { en: `${production.length} production unimplemented!/todo! placeholders in ${census.files} Rust sources${production.length ? `: ${production.slice(0, 4).map((hit) => `${hit.path}:${hit.line}`).join(", ")}` : ""}`, de: `${production.length} produktive unimplemented!/todo!-Platzhalter in ${census.files} Rust-Quellen${production.length ? `: ${production.slice(0, 4).map((hit) => `${hit.path}:${hit.line}`).join(", ")}` : ""}` },
      }));
      if (status !== "pass") process.exitCode = 1;
      return;
    }
    const production = census.jobs.filter((job) => !job.testOnly);
    const unreachable = production.filter((job) => job.classification === "BatchOnlyPendingRewrite");
    const perOwner = new Map<string, { migrated: number; unreachable: string[]; other: number }>();
    for (const job of production) {
      const owner = /^✏️s\/🔌️plugins\/([^/]+)/u.exec(job.path)?.[1] ?? job.path.split("/").slice(0, 3).join("/");
      const row = perOwner.get(owner) ?? { migrated: 0, unreachable: [], other: 0 };
      if (job.classification === "Migrated") row.migrated += 1;
      else if (job.classification === "BatchOnlyPendingRewrite") row.unreachable.push(job.command);
      else row.other += 1;
      perOwner.set(owner, row);
    }
    console.log("| owner | migrated | unreachable (BatchOnlyPendingRewrite) | other | unreachable commands |\n|---|---|---|---|---|");
    for (const [owner, row] of [...perOwner].sort((left, right) => right[1].unreachable.length - left[1].unreachable.length)) console.log(`| ${owner} | ${row.migrated} | ${row.unreachable.length} | ${row.other} | ${row.unreachable.join(", ")} |`);
    for (const line of census.unparsed) console.log(`[verify interactivity commands] non-literal declaration ${line}`);
    for (const disagreement of census.callDisagreements) console.log(`[verify interactivity commands] oracle disagreement ${disagreement}`);
    const status = unreachable.length === 0 && oracleAgrees && census.unparsed.length === 0 ? "pass" : "fail";
    console.log(`[verify interactivity commands] declarations=${production.length} unreachable=${unreachable.length} non-literal=${census.unparsed.length} oracle=${oracleAgrees ? "agrees" : "DISAGREES"}`);
    publishAcceptanceCheckResult(root, acceptanceCheckResult({
      check: "command-reachability",
      status,
      startedAt,
      measured: { declarations: production.length, unreachable: unreachable.length, nonLiteral: census.unparsed.length, oracleAgrees },
      summary: { en: `${unreachable.length}/${production.length} production commands unreachable (BatchOnlyPendingRewrite)${unreachable.length ? `: ${[...perOwner].filter(([, row]) => row.unreachable.length).map(([owner, row]) => `${owner} ${row.unreachable.length}`).join(", ")}` : ""}`, de: `${unreachable.length}/${production.length} produktive Befehle unerreichbar (BatchOnlyPendingRewrite)${unreachable.length ? `: ${[...perOwner].filter(([, row]) => row.unreachable.length).map(([owner, row]) => `${owner} ${row.unreachable.length}`).join(", ")}` : ""}` },
    }));
    if (status !== "pass") process.exitCode = 1;
  } finally {
    process.removeListener("SIGINT", cancel);
  }
}

/** 🏷️ The docstring census as gates (acceptance ledger 5.11): `at-emoji` fails on any docstring that opens with the `@emoji`
 * residue token instead of its emoji; `emoji-first` fails on any docstring that opens with neither an emoji nor a symbol
 * glyph. Both scan every tracked Rust / TypeScript source, cross-check the `@emoji` openers against `git grep`, print the
 * findings and publish the acceptance record.
 * @see 🧰️framework/🛍️products/🦑️repo/🔨️modules/🧪️test/🎯️acceptance/📋️orchestration/🟦️.ts `runDocstringCensus` */
async function runDocstringCensusGate(root: string, rule: string | undefined): Promise<void> {
  if (rule !== "at-emoji" && rule !== "emoji-first") throw new Error("usage: verify docstrings <at-emoji|emoji-first>");
  const { acceptanceCheckResult, publishAcceptanceCheckResult, runDocstringCensus } = await import("./🧰️framework/🛍️products/🦑️repo/🔨️modules/🧪️test/🎯️acceptance/📋️orchestration/🟦️.ts");
  const controller = new AbortController();
  const cancel = (): void => controller.abort();
  process.once("SIGINT", cancel);
  const startedAt = new Date();
  try {
    const census = runDocstringCensus(root, controller.signal, (line) => console.error(`[verify docstrings] ${line}`));
    const atEmoji = census.hits.filter((hit) => hit.rule === "at-emoji");
    const noEmoji = census.hits.filter((hit) => hit.rule === "no-emoji");
    const failing = rule === "at-emoji" ? atEmoji : census.hits;
    for (const hit of failing.slice(0, 200)) console.log(`[verify docstrings] ${hit.rule} ${hit.path}:${hit.line} ${hit.text}`);
    for (const disagreement of census.disagreements) console.log(`[verify docstrings] oracle disagreement ${disagreement}`);
    const status = failing.length === 0 && census.disagreements.length === 0 ? "pass" : "fail";
    console.log(`[verify docstrings] rule=${rule} files=${census.files} at-emoji=${atEmoji.length} no-emoji=${noEmoji.length} oracle=${census.disagreements.length === 0 ? "agrees" : "DISAGREES"}`);
    publishAcceptanceCheckResult(root, acceptanceCheckResult({
      check: rule === "at-emoji" ? "docstring-at-emoji" : "docstring-emoji-first",
      status,
      startedAt,
      measured: { files: census.files, atEmoji: atEmoji.length, noEmoji: noEmoji.length, oracleAgrees: census.disagreements.length === 0 },
