const INTERACTIVITY_TOOL_RUN_INDEXES = new WeakMap<readonly InteractivityToolRunSource[], InteractivityToolRunIndex>();

/** 📍️ True when `path` is `prefix` or lies below it. */
function interactivityToolRunWithin(path: string, prefix: string): boolean {
  return path === prefix || path.startsWith(`${prefix}/`);
}

/** 📍️ A requirement scope entry as a repo-relative path. */
function interactivityToolRunScopePath(root: string, entry: string): string {
  return entry.startsWith("✏️s/") || entry.startsWith("🧰️framework/") ? entry : `${root}/${entry}`;
}

/** ✂️ Line-aligned code of one source: comments blanked, string literals kept, Rust `#[cfg(test)]` items emptied. */
function interactivityToolRunCode(source: InteractivityToolRunSource): string[] {
  const lines = source.text.split(/\r?\n/);
  const tests = source.path.endsWith(".rs") ? [...policyTestModSpans(lines), ...interactivityCfgTestItemSpans(lines)] : [];
  let depth = 0;
  return lines.map((raw, index) => {
    const masked = policyMaskLiterals(raw);
    let code = "";
    for (let at = 0; at < raw.length; ) {
      const pair = masked.slice(at, at + 2);
      if (depth > 0) {
        depth += pair === "/*" ? 1 : pair === "*/" ? -1 : 0;
        at += pair === "/*" || pair === "*/" ? 2 : 1;
      } else if (pair === "//") {
        break;
      } else if (pair === "/*") {
        depth = 1;
        at += 2;
      } else {
        code += raw[at];
        at += 1;
      }
    }
    return policyLineInTestMod(tests, index + 1) ? "" : code;
  });
}

/** 🧱️ The innermost `opener … }` span of `text` (literal-safe) that encloses offset `at`. */
function interactivityToolRunEnclosing(text: string, at: number, opener: RegExp): string | undefined {
  if (at < 0) return undefined;
  const masked = policyMaskLiterals(text);
  let enclosing: string | undefined;
  for (const match of masked.matchAll(opener)) {
    const open = match.index + match[0].length - 1;
    if (open > at) break;
    let depth = 0;
    let close = masked.length;
    for (let index = open; index < masked.length; index += 1) {
      depth += masked[index] === "{" ? 1 : masked[index] === "}" ? -1 : 0;
      if (depth === 0) {
        close = index;
        break;
      }
    }
    if (close >= at) enclosing = text.slice(match.index, close + 1);
  }
  return enclosing;
}

/** 🗂️ Code lines per source plus every Tool/UtilityDefinition declaration under `✏️s/`, its resolved id and whether it declares `run`. */
function interactivityToolRunIndex(sources: readonly InteractivityToolRunSource[]): InteractivityToolRunIndex {
  const cached = INTERACTIVITY_TOOL_RUN_INDEXES.get(sources);
  if (cached) return cached;
  const code = new Map(sources.map((source) => [source.path, interactivityToolRunCode(source)] as const));
  const constants = new Map<string, Map<string, Set<string>>>();
  const plugin = (path: string) => path.split("/").slice(0, 3).join("/");
  for (const [path, lines] of code) {
    if (!path.endsWith(".rs")) continue;
    for (const match of lines.join("\n").matchAll(/\bconst\s+([A-Z][A-Z0-9_]*)\s*:\s*&(?:'static\s+)?str\s*=\s*"([^"]*)"/g)) {
      for (const key of [path, plugin(path)]) {
        const byName = constants.get(key) ?? new Map<string, Set<string>>();
        byName.set(match[1]!, (byName.get(match[1]!) ?? new Set<string>()).add(match[2]!));
        constants.set(key, byName);
      }
    }
  }
  const resolve = (path: string, expression: string): string | undefined => {
    const literal = expression.match(/^"([^"]*)"$/);
    if (literal) return literal[1];
    const name = expression.match(/^(?:[\w]+::)*([A-Z][A-Z0-9_]*)$/)?.[1];
    if (!name) return undefined;
    for (const key of [path, plugin(path)]) {
      const values = constants.get(key)?.get(name);
      if (values?.size === 1) return [...values][0];
    }
    return undefined;
  };
  const declarations: InteractivityToolRunDeclaration[] = [];
  for (const [path, lines] of code) {
    if (!path.startsWith("✏️s/") || !path.endsWith(".rs")) continue;
    const joined = lines.join("\n");
    for (const match of joined.matchAll(/\b(Tool|Utility)Definition::new\(\s*([^,()]+?)\s*,/g)) {
      const id = resolve(path, match[2]!.trim());
      if (id === undefined) continue;
      const kind = match[1] as "Tool" | "Utility";
      const literal = interactivityToolRunEnclosing(joined, match.index, new RegExp(`\\b${kind}Definition\\s*\\{`, "g"));
      const body = interactivityToolRunEnclosing(joined, match.index, /\bfn\s+\w+[^{;]*\{/g);
      const run = (literal !== undefined && /\brun\s*:\s*Some\s*\(/.test(literal)) || (body !== undefined && /\.run\s*=\s*Some\s*\(/.test(body));
      declarations.push({ id, kind, file: path, line: joined.slice(0, match.index).split("\n").length, run });
    }
  }
  const index = { code, declarations };
  INTERACTIVITY_TOOL_RUN_INDEXES.set(sources, index);
  return index;
}

/** 🧰️ Tools the lifecycle predicate governs: every requirement row, plus every run-declaring tool no row names (scoped to its declaring directory). */
function interactivityToolRunTools(sources: readonly InteractivityToolRunSource[], requirements: readonly InteractivityToolRunRequirement[]): InteractivityToolRunTool[] {
  const { declarations } = interactivityToolRunIndex(sources);
  const rows = requirements.map((row) => ({
    label: `${row.toolId} (${row.root}, lane ${row.lane}, inventory ${row.inventory})`,
    root: row.root,
    scope: row.scope.map((entry) => interactivityToolRunScopePath(row.root, entry)),
    flat: false,
    verbs: row.verbs,
    measures: row.measures,
    declared: declarations.some((declaration) => declaration.run && declaration.id === row.toolId && interactivityToolRunWithin(declaration.file, row.root)),
  }));
  const discovered = declarations
    .filter((declaration) => declaration.run && !requirements.some((row) => row.toolId === declaration.id && interactivityToolRunWithin(declaration.file, row.root)))
    .map((declaration) => {
      const directory = declaration.file.slice(0, declaration.file.lastIndexOf("/"));
      return { label: `${declaration.id} (${declaration.file}:${declaration.line})`, root: directory, scope: [directory], flat: true, verbs: [], measures: [], declared: true };
    });
  return [...rows, ...discovered];
}

/** 📍️ True when `path` belongs to the tool's own files. */
function interactivityToolRunInScope(tool: InteractivityToolRunTool, path: string): boolean {
  return tool.scope.some((entry) => (tool.flat ? path.slice(0, path.lastIndexOf("/")) === entry : interactivityToolRunWithin(path, entry)));
}

/** 🔎️ A word-bounded token matcher that treats `-` as part of a token. */
function interactivityToolRunToken(token: string): RegExp {
  return new RegExp(`(?<![\\w-])${token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?![\\w-])`);
}

/** 📚️ Every repo runtime Rust/TS source a tool-run predicate can hit: under a requirement root or scope, or carrying one of their trigger tokens. */
export function interactivityToolRunPolicySources(repoRoot: string, requirements: readonly InteractivityToolRunRequirement[]): InteractivityToolRunSource[] {
  const anchors = requirements.flatMap((row) => [row.root, ...row.scope.map((entry) => interactivityToolRunScopePath(row.root, entry))]);
  return policyWalkRelFiles(repoRoot, ["✏️s", "🧰️framework"], (_path, name) => /\.(?:rs|tsx?)$/.test(name))
    .filter(interactivityIsRuntimeSource)
    .flatMap((path) => {
      const text = policyReadFileSafe(repoRoot, path);
      return anchors.some((anchor) => interactivityToolRunWithin(path, anchor)) || INTERACTIVITY_TOOL_RUN_TRIGGER.test(text) ? [{ path, text }] : [];
    });
}

/** ⏯️ (1) Once a tool declares `run`, no per-plugin run verb, lifecycle state or plugin-local progress/cancel measure survives (`📋️tool-run-contract.md` §2.5, §3.6). */
export function interactivityToolRunLocalLifecycleFailures(sources: readonly InteractivityToolRunSource[], requirements: readonly InteractivityToolRunRequirement[]): InteractivityToolRunFinding[] {
  const { code } = interactivityToolRunIndex(sources);
  const findings: InteractivityToolRunFinding[] = [];
  for (const tool of interactivityToolRunTools(sources, requirements).filter((candidate) => candidate.declared)) {
    const verbs = tool.verbs.map((verb) => [verb, interactivityToolRunToken(verb)] as const);
    const measures = tool.measures.map((measure) => [measure, interactivityToolRunToken(measure)] as const);
    for (const [path, lines] of code) {
      const rooted = interactivityToolRunWithin(path, tool.root);
      const scoped = interactivityToolRunInScope(tool, path);
      if (!rooted && !scoped) continue;
      lines.forEach((line, index) => {
        const hits = [...(rooted ? verbs : []), ...(scoped ? measures : [])].filter(([, pattern]) => pattern.test(line)).map(([token]) => token);
        if (scoped) hits.push(...INTERACTIVITY_TOOL_RUN_LOCAL_LIFECYCLE.flatMap((pattern) => line.match(pattern)?.[0] ?? []));
        for (const hit of new Set(hits)) findings.push({ file: path, line: index + 1, text: `[⏯️ local-lifecycle] ${tool.label}: ${hit} survives next to a declared ToolRunDefinition; use the framework toolRun* actions, ToolRunState and the ToolRun panel (contract §2.5, §3.6)` });
      });
    }
  }
  return findings;
}

/** ⏯️ (2) No tried-candidate ring, `fillBuildPreview` tail or fill preview JSON cap survives anywhere; tested candidates travel only as trace pages (`📋️tool-run-contract.md` §3.2, §3.6). */
export function interactivityToolRunLegacyTraceFailures(sources: readonly InteractivityToolRunSource[]): InteractivityToolRunFinding[] {
  const { code } = interactivityToolRunIndex(sources);
  const findings: InteractivityToolRunFinding[] = [];
  for (const [path, lines] of code) {
    lines.forEach((line, index) => {
      const hit = line.match(INTERACTIVITY_TOOL_RUN_LEGACY_TRACE)?.[0];
      if (hit) findings.push({ file: path, line: index + 1, text: `[⏯️ legacy-trace] ${hit} survives; tested candidates travel only as ToolRunTracePage deltas rendered by the ToolRunTraceLayer (contract §3.2, §3.6)` });
    });
  }
  return findings;
}

/** ⏯️ (3) Every `algorithmic-mutating` tool of [[INTERACTIVITY_TOOL_RUN_REQUIREMENTS]] declares `run: Some(ToolRunDefinition)` on its Tool/UtilityDefinition, and every table row still points at real sources (`📋️tool-run-contract.md` §2.4, §3.7). */
export function interactivityToolRunDeclarationFailures(sources: readonly InteractivityToolRunSource[], requirements: readonly InteractivityToolRunRequirement[]): InteractivityToolRunFinding[] {
  const { code, declarations } = interactivityToolRunIndex(sources);
  const paths = [...code.keys()];
  const findings: InteractivityToolRunFinding[] = [];
  const seen = new Set<string>();
  for (const row of requirements) {
    const label = `[⏯️ declaration] ${row.toolId} (${row.root}, lane ${row.lane}, inventory ${row.inventory})`;
    const key = `${row.root}#${row.toolId}`;
    if (seen.has(key)) findings.push({ file: row.root, line: 0, text: `${label}: duplicate requirement row` });
    seen.add(key);
    if (!paths.some((path) => interactivityToolRunWithin(path, row.root))) {
      findings.push({ file: row.root, line: 0, text: `${label}: requirement root has no sources (stale row)` });
      continue;
    }
    if (row.scope.length > 0 && !row.scope.some((entry) => paths.some((path) => interactivityToolRunWithin(path, interactivityToolRunScopePath(row.root, entry))))) findings.push({ file: row.root, line: 0, text: `${label}: no scope entry exists any more (stale row)` });
    const matching = declarations.filter((declaration) => declaration.id === row.toolId && interactivityToolRunWithin(declaration.file, row.root));
    if (matching.some((declaration) => declaration.run)) continue;
    const found = matching[0];
    findings.push(found ? { file: found.file, line: found.line, text: `${label}: ${found.kind}Definition "${row.toolId}" declares no run: Some(ToolRunDefinition) (contract §2.4)` } : { file: row.root, line: 0, text: `${label}: no Tool/UtilityDefinition "${row.toolId}" exists; the algorithm is not a tool run yet (contract §2.4, §3.7)` });
  }
  return findings;
}

/** ⏯️ (4) `toolRun*` action ids are framework-reserved: plugins never declare, literal-copy or route them (`📋️tool-run-contract.md` §2.5). */
export function interactivityToolRunReservedActionFailures(sources: readonly InteractivityToolRunSource[]): InteractivityToolRunFinding[] {
  const { code } = interactivityToolRunIndex(sources);
  const findings: InteractivityToolRunFinding[] = [];
  for (const [path, lines] of code) {
    if (!path.startsWith("✏️s/")) continue;
    lines.forEach((line, index) => {
      const hit = INTERACTIVITY_TOOL_RUN_RESERVED.map((pattern) => line.match(pattern)?.[0]).find((match) => match !== undefined);
      if (hit) findings.push({ file: path, line: index + 1, text: `[⏯️ reserved-action] ${hit.trim()}: toolRun* actions are framework-reserved and injected from ToolRunDefinition; reference the framework constants only to dispatch (contract §2.5)` });
    });
  }
  return findings;
}
//#endregion ⏯️ToolRunPolicy

//#region 🚫️HistoryClosure
/**
 * 🚫️ One closure rule of the non-destructive history contract (ticket `26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING`,
 * `📋️design.md` §13.2, §17.5, §17.7, §20): a token that must not survive in the scanned trees. `anchors` are literal substrings a file must
 * contain before the rule's `pattern` runs, `applies` narrows the files the rule reads, `allow` names the files whose hit is a deliberate negative case, `functions` the enclosing Rust functions
 * whose hit is a declared whole-document intent.
 */
export type HistoryClosureRule = { readonly id: string; readonly anchors: readonly string[]; readonly pattern: RegExp; readonly applies: (path: string) => boolean; readonly allow: readonly string[]; readonly functions?: readonly string[]; readonly within?: RegExp; readonly unless?: RegExp; readonly item?: { readonly header: RegExp; readonly unless: RegExp }; readonly reason: string };

/** 🚫️ One closure violation anchored to its rule, a repo-relative file and a 1-based line. */
export type HistoryClosureFinding = { readonly rule: string; readonly file: string; readonly line: number; readonly text: string };

const HISTORY_CLOSURE_ROOTS = ["✏️s", "🧰️framework", "🌎️hub"] as const;
const HISTORY_CLOSURE_SOURCE = /\.(?:rs|ts|tsx|js|py|feature|json)$/;
const HISTORY_CLOSURE_TESTS = /\/🧪️tests\/|\/🧪️testing\//;
const HISTORY_CLOSURE_STORE = "🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/";
const HISTORY_CLOSURE_PLUGIN_TREES = ["✏️s/", "🌎️hub/🧩️compositions/"] as const;

/** 🧩️ True for production (non-test) code of a plugin tree. */
function historyClosurePluginProduction(path: string): boolean {
  return HISTORY_CLOSURE_PLUGIN_TREES.some((tree) => path.startsWith(tree)) && !HISTORY_CLOSURE_TESTS.test(path) && path.endsWith(".rs");
}

/**
 * 🚫️ The closure rules. Every lane commits through a tool transaction (artifact) or one plain config edit at gesture end
 * (§20.1): no amend constructor, no `AmendLast*` command, no coalesce key on any emission, edit, wire frame or fixture, no
 * gesture bracket verb, no host-snapshot bracket. Plugins never hand-build a `protocol::Edit` (the Store authority's
 * `next_edit` mints it) and never hand-declare a fold footprint (derived from the leaf's `x-semio-inverse-rows`, §20.5).
 */
export const HISTORY_CLOSURE_RULES: readonly HistoryClosureRule[] = [
  { id: "amend-emit", anchors: ["Emit::amend", "amend_config"], pattern: /\b(?:Action)?Emit::amend\b|\bamend_config\b/, applies: () => true, allow: [], reason: "a gesture is a tool transaction (artifact lane) or one config edit at gesture end (config lane); no emission amends the previous edit" },
  { id: "amend-last", anchors: ["AmendLast", "amendLast"], pattern: /\bAmendLast\w*|\bamendLast\w*/, applies: () => true, allow: [], reason: "the Store has no amend command on any lane; a transaction-scoped open edit (§15) is the only growing edit" },
  { id: "coalesce-key", anchors: ["coalesce_key", "coalesceKey"], pattern: /\bcoalesce_key\b|\bcoalesceKey\b|\bset_coalesce_key\b/, applies: () => true, allow: ["🌎️hub/🧩️compositions/🪐️space/🧪️testing/🧫️fixtures/🔮️ownership/🔣️.json"], reason: "no emission, edit, digest, wire frame, persisted record or fixture carries a coalesce key; history rows group by TransactionRef" },
  { id: "preview-contract", anchors: ["UtilityPreviewContract"], pattern: /\bUtilityPreviewContract\b/, applies: () => true, allow: [], reason: "the actions-vs-tools contract is `🔖️ToolContract`; there is no preview pattern beside tool machines" },
  { id: "bracket-verb", anchors: ["transformBegin", "transformEnd", "paintStrokeBegin", "paintStrokeEnd"], pattern: /\b(?:transform|paintStroke)(?:Begin|End)\b/, applies: () => true, allow: ["🧰️framework/🔨️modules/🛂️manifest/🧫️fixtures/🖐️gumball-verb-audience.json", "✏️s/🔌️plugins/🧩️puzzle/🗿️artifacts/🧊️3d/🏅️standards/🔖️1/🪆️subsets/✳️any/✏️editor/🧪️tests/🔬️unit/🦀️.rs"], reason: "a gesture is one tool-machine press with stream/commit/abort phases; no bracket verb exists" },
  { id: "host-snapshot-bracket", anchors: ["setHostSnapshot", "SetHostSnapshot", "set_host_snapshot"], pattern: /\bsetHostSnapshot\b|\bSetHostSnapshot\b|\bset_host_snapshot\b/, applies: (path) => !HISTORY_CLOSURE_TESTS.test(path), allow: ["🧰️framework/🔨️modules/🛠️tool-machine/🧫️fixtures/🧫️node-graph-edit-rows/🔣️.json"], reason: "node-graph hosts journal id-keyed rows (move/connect/delete); a whole host snapshot is never a history mutation (refusal laws and the shared refusal fixture name it)" },
  { id: "edit-literal", anchors: ["Edit"], pattern: /\bprotocol::Edit\s*\{|(?<![\w:])Edit\s*\{\s*line\s*:/, applies: historyClosurePluginProduction, allow: [], reason: "plugins never hand-build an edit; `ArtifactStoreOneItemLiveAuthority::next_edit` mints it from the Store authority" },
  { id: "release-plain-commit", anchors: ["artifact_mutations", "Emit::mutations(", "Emit::commit("], pattern: /\bartifact_mutations\s*:|\bEmit::(?:mutations|commit)\(/, applies: historyClosurePluginProduction, allow: [], within: /pointer_up|_release$|^release_/, unless: /\b(?:commit|stream|abort)_transaction\b|\bnode_drag\w*|\bToolStep::/, reason: "a pointer/drag sequence commits through its tool machine (`commit_transaction`); a release handler never publishes an absolute final-state leaf (L6)" },
  { id: "footprint-hand", anchors: ["for_one_", "ArtifactStoreOneItemFootprint"], pattern: /\bfor_one_invertible_item\b|\bfor_one_item\b|\bArtifactStoreOneItemFootprint\s*\{\s*work_items\b/, applies: (path) => path.endsWith(".rs") && !path.startsWith(HISTORY_CLOSURE_STORE) && !HISTORY_CLOSURE_TESTS.test(path), allow: [], reason: "a fold footprint is derived from the leaf's `x-semio-inverse-rows` through `ArtifactStoreOneItemFootprint::for_leaf`; a hand count under-declares multi-row inverses" },
  { id: "footprint-default", anchors: ["INPUT_SCHEMAS"], pattern: /\bconst\s+INPUT_SCHEMAS\b/, applies: (path) => path.endsWith(".rs") && !HISTORY_CLOSURE_TESTS.test(path), allow: [], item: { header: /^\s*impl\b.*(?<!Semantic)\bMutation</, unless: /\bfn\s+inverse_rows\b/ }, reason: "a hand-written aggregate that forwards leaf payload schemas forwards their `x-semio-inverse-rows` too (`fn inverse_rows`); the default single row under-declares every multi-row leaf (§20.5, CLOSURE-4)" },
];

/** 🪧️ The header line and brace-balanced body of the Rust `impl`/`trait` item enclosing `index` in `lines`, or `undefined`. */
function historyClosureEnclosingItem(lines: readonly string[], index: number): { readonly header: string; readonly body: string } | undefined {
  for (let cursor = index; cursor >= 0; cursor--) if (/^\s*(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?(?:impl|trait)\b/.test(lines[cursor]!)) return { header: lines[cursor]!, body: historyClosureFunctionBody(lines, cursor) };
  return undefined;
}

/** 🧱️ The brace-balanced body text of the Rust function whose `fn` line is `start` in `lines`. */
function historyClosureFunctionBody(lines: readonly string[], start: number): string {
  let depth = 0;
  let opened = false;
  const body: string[] = [];
  for (let cursor = start; cursor < lines.length; cursor++) {
    body.push(lines[cursor]!);
    for (const character of lines[cursor]!) {
      if (character === "{") [depth, opened] = [depth + 1, true];
      else if (character === "}") depth--;
    }
    if (opened && depth <= 0) break;
  }
  return body.join("\n");
}

/** 🔎️ The line index of the Rust `fn` enclosing `index` in `lines` (nearest preceding `fn name`), or `-1`. */
function historyClosureEnclosingFunctionLine(lines: readonly string[], index: number): number {
  for (let cursor = index; cursor >= 0; cursor--) if (/\bfn\s+\w+/.test(lines[cursor]!)) return cursor;
  return -1;
}

/** 🔎️ The Rust function enclosing `index` in `lines` (nearest preceding `fn name`), or `undefined`. */
function historyClosureEnclosingFunction(lines: readonly string[], index: number): string | undefined {
  for (let cursor = index; cursor >= 0; cursor--) {
    const name = lines[cursor]!.match(/\bfn\s+(\w+)/)?.[1];
    if (name) return name;
  }
  return undefined;
}

/** 🚫️ Every closure violation in `sources` under `rules` (default [[HISTORY_CLOSURE_RULES]]); pure, so planted-violation tests drive it directly. */
export function historyClosureFindings(sources: readonly { readonly path: string; readonly text: string }[], rules: readonly HistoryClosureRule[] = HISTORY_CLOSURE_RULES): HistoryClosureFinding[] {
  const findings: HistoryClosureFinding[] = [];
  for (const { path, text } of sources) {
    const active = rules.filter((rule) => rule.anchors.some((anchor) => text.includes(anchor)) && rule.applies(path) && !rule.allow.includes(path));
    if (active.length === 0) continue;
    const lines = text.split("\n");
    lines.forEach((line, index) => {
      for (const rule of active) {
        if (!rule.anchors.some((anchor) => line.includes(anchor))) continue;
        const hit = line.match(rule.pattern)?.[0];
        if (hit === undefined) continue;
        if (rule.functions && path.endsWith(".rs") && rule.functions.includes(historyClosureEnclosingFunction(lines, index) ?? "")) continue;
        if (rule.within) {
          const start = historyClosureEnclosingFunctionLine(lines, index);
          const name = start < 0 ? "" : (lines[start]!.match(/\bfn\s+(\w+)/)?.[1] ?? "");
          if (!rule.within.test(name) || (rule.unless && rule.unless.test(historyClosureFunctionBody(lines, start)))) continue;
        }
        if (rule.item) {
          const item = historyClosureEnclosingItem(lines, index);
          if (item === undefined || !rule.item.header.test(item.header) || rule.item.unless.test(item.body)) continue;
        }
        findings.push({ rule: rule.id, file: path, line: index + 1, text: `[🚫️ ${rule.id}] ${hit}: ${rule.reason}` });
      }
    });
  }
  return findings;
}

/** 🗂️ The git-visible (tracked + unignored) source files of the closure roots, read once. */
export function historyClosureSources(repoRoot: string): { readonly path: string; readonly text: string }[] {
  const listed = Bun.spawnSync(["git", "ls-files", "-co", "--exclude-standard", "-z", "--", ...HISTORY_CLOSURE_ROOTS], { cwd: repoRoot });
  if (listed.exitCode !== 0) throw new Error(`[verify history-closure] git-visible inventory failed: ${listed.stderr.toString()}`);
  const paths = [...new Set(listed.stdout.toString().split("\0").map((path) => path.normalize("NFC")))].filter((path) => HISTORY_CLOSURE_SOURCE.test(path) && !path.split("/").some((segment) => POLICY_SKIP_DIRS.has(segment)));
  return paths.flatMap((path) => {
    try {
      return [{ path, text: readFileSync(join(repoRoot, path), "utf8") }];
    } catch {
      return [];
    }
  });
}

/** 🚫️ The closure gate as breach records: one high-priority breach per finding. */
export function policyHistoryClosureBreaches(repoRoot: string): BreachRecord[] {
  return historyClosureFindings(historyClosureSources(repoRoot)).map((finding) => ({
    id: `history-closure-${finding.rule}-${finding.file}:${finding.line}`,
    summary: `${finding.file}:${finding.line} ${finding.text}`,
    kind: `history-closure/${finding.rule}`,
    scope: finding.file,
    priority: "high",
    reason: HISTORY_CLOSURE_RULES.find((rule) => rule.id === finding.rule)?.reason ?? finding.rule,
    solution: "Delete the legacy path: commit gestures through a ToolTransaction or one config edit at gesture end, mint edits with `next_edit`, derive footprints with `for_leaf` (ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING §20).",
  }));
}
//#endregion 🚫️HistoryClosure



export function interactivityLiveReconcileFailures(reconcileSource: string, patchesSource: string, reactorSource: string, valueSource: string, schemaSource = ""): string[] {
  const reconcile = interactivityProductionSource(reconcileSource);
  const patches = interactivityProductionSource(patchesSource);
  const reactor = interactivityProductionSource(reactorSource);
  const value = interactivityProductionSource(valueSource);
  const schema = interactivityProductionSource(schemaSource);
  const driveStart = reconcile.indexOf("    pub fn drive_one(&mut self, cx:");
  const driveEnd = reconcile.indexOf("    pub fn fault(&self)", driveStart);
  const drive = reconcile.slice(driveStart, driveEnd);
  const turnPatchBridgeStart = reactor.indexOf("let owner = std::mem::take(&mut result.ui_patches)");
  const turnPatchBridge = reactor.slice(turnPatchBridgeStart, reactor.indexOf("//#endregion 🔀️BudgetBridge", turnPatchBridgeStart));
  const rendererRetainedStart = reactor.indexOf("struct RetainedDocumentBuild");
  const rendererRetained = reactor.slice(rendererRetainedStart, reactor.indexOf("struct PendingJobProgressPresentation", rendererRetainedStart));
  const commandDocumentStart = reactor.indexOf("const COMMAND_DOCUMENT_RETIREMENT_CAPACITY");
  const commandDocuments = reactor.slice(commandDocumentStart, reactor.indexOf("struct KernelPoolState", commandDocumentStart));
  const commandExchangeStart = reactor.indexOf("async fn exchange_commands(&mut self");
  const commandExchange = reactor.slice(commandExchangeStart, reactor.indexOf("async fn run_turn", commandExchangeStart));
  const shellDocumentStart = reactor.indexOf("const SHELL_DOCUMENT_RETIREMENT_CAPACITY");
  const shellDocuments = reactor.slice(shellDocumentStart, reactor.indexOf("pub struct ShellState", shellDocumentStart));
  const shellRefreshStart = reactor.indexOf("pub async fn refresh_ui(&mut self)");
  const shellRefresh = reactor.slice(shellRefreshStart, reactor.indexOf("fn queue_host_effects", shellRefreshStart));
  const rendererSequenceStart = reactor.indexOf("struct RendererSequenceAuthority");
  const rendererSequence = reactor.slice(rendererSequenceStart, reactor.indexOf("const JOB_PROGRESS_PRESENTATION_CAPACITY", rendererSequenceStart));
  const windowMeasureStart = reactor.indexOf("fn measures_for_kind");
  const windowMeasure = reactor.slice(windowMeasureStart, reactor.indexOf("fn render_window_engagement_rail", windowMeasureStart));
