    /// `maintenance_step` pumps, one bounded unit per stage rotation.
    fn drain_and_close_fixture(app: &mut VcsArtifactApp<TestApp>) {
        for _ in 0..64 {
            for stage in 0..MAINTENANCE_STAGES {
