        let refused = app.handle_action(semio_framework::HOST_EVENT_ACTION_ID, Some(&dv(json!({ "windowId": "main-1", "kind": "wobble" }))), &under).await;
        assert_eq!(refused.err().map(|fault| fault.code), Some(FaultCode::new("hostEvent.invalid")));
